"""Validate one fresh profiler capture without claiming any gameplay optimization."""
from pathlib import Path
import argparse,hashlib,json
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--fixture',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();a.output.mkdir(parents=True,exist_ok=False);prep=json.loads((a.fixture/'preparation.json').read_text());old=Path(prep['ROM']).parent.parent/'root-chip-native-audio-v3/candidate';new=json.loads((a.fixture/'audio-native.json').read_text());guard=json.loads((a.fixture/'ownership-guards.json').read_text());prior=json.loads((old/'audio-native.json').read_text());assert new==prior and new['passed']and guard['passed'];assert(a.fixture/'cadence.csv').read_bytes()==(old/'cadence.csv').read_bytes();summary=json.loads((a.fixture/'profile-summary.json').read_text());assert summary['passed']and summary['source_returns']==910 and summary['wall_frames']==1300
 spans=[json.loads(x)for x in(a.fixture/'profile-spans.jsonl').read_text().splitlines()];events=[json.loads(x)for x in(a.fixture/'profile-boundaries.jsonl').read_text().splitlines()];snaps=[json.loads(x)for x in(a.fixture/'profile-snapshots.jsonl').read_text().splitlines()];raw=(a.fixture/'profile-snapshots.ram').read_bytes();assert len(snaps)<=64 and len(raw)==11264*len(snaps)==summary['snapshot_bytes'];assert all(q['ramBytes']==11264 and q['ramOffset']==i*11264 for i,q in enumerate(snaps));assert all(q['cpuCycles']==q['elapsedCycles']-q['interruptCycles']>=q['exclusiveCpuCycles']>=0 for q in spans)
 lag=[q for q in events if q['kind']=='NMI-entry'and q['nmiDisable']!=0];assert lag and any(q['sourceCalls']in[2,3]for q in lag),'First actual missed boundary captured';assert any(q['detail']=='GameLoop'for q in snaps)and any(q['detail']=='AudioUpdate'for q in snaps);assert any(q['kind']=='post-hardware-NMI-entry'for q in snaps);assert{'AudioUpdate','ChNativeSourcePlay','GameLoop'}<={q['name']for q in spans}
 result=dict(passed=True,native_completed=True,optimization_accepted=False,production_mutated=False,ROM_sha256=prep['ROM_sha256'],original_source_guard_and_native_counts_semantically_equal=True,original_cadence_byteexact=True,old_unfixed_DMA_starts=880,baseline_historical_DMA_starts=908,original28missed_draw_defect_retained=True,actual_lag_entries=lag[:3],captured_function_spans=len(spans),captured_snapshots=len(snaps),entry_state_bytes=len(raw),aggregate=summary['aggregate'],scope='One read-only capture qualifies instrumentation and supplies actual cost/entry-state evidence only. Original8b4 idle lag remains; no optimization, frame improvement, waveform or campaign result.',tool_sha256=sha(__file__));(a.output/'proof.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({k:v for k,v in result.items()if k not in['aggregate','actual_lag_entries']},indent=2))
if __name__=='__main__':main()
